using System.Collections.Generic;
using UnityEngine;

namespace Parasite
{
    /// <summary>
    /// Runtime material creation. Clones template materials stored in Resources/Materials so the
    /// required URP shader variants (emission, normal maps, transparency) survive build stripping.
    /// Templates are generated by Parasite/Setup/Project Setup (ProjectSetup.cs).
    /// </summary>
    public static class MatFactory
    {
        static readonly Dictionary<string, Material> cache = new();
        static Material litTemplate, transparentTemplate, unlitTemplate;

        static readonly int BaseColor = Shader.PropertyToID("_BaseColor");
        static readonly int BaseMap = Shader.PropertyToID("_BaseMap");
        static readonly int BumpMap = Shader.PropertyToID("_BumpMap");
        static readonly int Smoothness = Shader.PropertyToID("_Smoothness");
        static readonly int Metallic = Shader.PropertyToID("_Metallic");
        static readonly int EmissionColor = Shader.PropertyToID("_EmissionColor");

        static Material Template(ref Material slot, string resource, string shaderFallback)
        {
            if (slot) return slot;
            slot = Resources.Load<Material>(resource);
            if (!slot)
            {
                var sh = Shader.Find(shaderFallback) ?? Shader.Find("Universal Render Pipeline/Lit") ?? Shader.Find("Standard");
                slot = new Material(sh);
            }
            return slot;
        }

        public static Material Lit(Color color, float smoothness = 0.35f, float metallic = 0f,
            Texture albedo = null, Texture normal = null, Vector2 tiling = default, bool emissive = false)
        {
            string key = $"lit:{color}:{smoothness}:{metallic}:{(albedo ? albedo.GetInstanceID() : 0)}:{(normal ? normal.GetInstanceID() : 0)}:{tiling}:{emissive}";
            if (cache.TryGetValue(key, out var m) && m) return m;
            m = new Material(Template(ref litTemplate, "Materials/LitTemplate", "Universal Render Pipeline/Lit"));
            m.SetColor(BaseColor, color);
            m.color = color;
            m.SetFloat(Smoothness, smoothness);
            m.SetFloat(Metallic, metallic);
            if (albedo) { m.SetTexture(BaseMap, albedo); m.mainTexture = albedo; }
            if (normal) { m.SetTexture(BumpMap, normal); m.EnableKeyword("_NORMALMAP"); }
            if (tiling != default) m.SetTextureScale(BaseMap, tiling);
            m.SetColor(EmissionColor, Color.black);
            if (emissive) m.EnableKeyword("_EMISSION");
            cache[key] = m;
            return m;
        }

        static readonly Dictionary<string, Texture2D> texCache = new();

        /// <summary>Texture from Resources (cached, null if missing).</summary>
        public static Texture2D Tex(string resourcePath)
        {
            if (string.IsNullOrEmpty(resourcePath)) return null;
            if (texCache.TryGetValue(resourcePath, out var t)) return t;
            t = Resources.Load<Texture2D>(resourcePath);
            texCache[resourcePath] = t;
            return t;
        }

        /// <summary>A material whose emission can be animated (e.g. possession glow). Not cached: one per owner.</summary>
        public static Material LitUnique(Color color, float smoothness, float metallic, Texture albedo, Texture normal, float tiling, float normalStrength = 1f)
        {
            var m = LitUnique(color, smoothness, metallic);
            if (albedo) { m.SetTexture(BaseMap, albedo); m.SetTextureScale(BaseMap, new Vector2(tiling, tiling)); }
            if (normal) { m.SetTexture(BumpMap, normal); m.SetFloat("_BumpScale", normalStrength); m.EnableKeyword("_NORMALMAP"); }
            return m;
        }

        public static Material LitUnique(Color color, float smoothness = 0.35f, float metallic = 0f)
        {
            var m = new Material(Template(ref litTemplate, "Materials/LitTemplate", "Universal Render Pipeline/Lit"));
            m.SetColor(BaseColor, color);
            m.SetFloat(Smoothness, smoothness);
            m.SetFloat(Metallic, metallic);
            m.EnableKeyword("_EMISSION");
            m.SetColor(EmissionColor, Color.black);
            m.globalIlluminationFlags = MaterialGlobalIlluminationFlags.RealtimeEmissive;
            return m;
        }

        public static Material Emissive(Color baseColor, Color emission)
        {
            string key = $"emis:{baseColor}:{emission}";
            if (cache.TryGetValue(key, out var m) && m) return m;
            m = new Material(Template(ref litTemplate, "Materials/LitTemplate", "Universal Render Pipeline/Lit"));
            m.SetColor(BaseColor, baseColor);
            m.EnableKeyword("_EMISSION");
            m.SetColor(EmissionColor, emission);
            cache[key] = m;
            return m;
        }

        public static Material Transparent(Color color)
        {
            string key = $"tr:{color}";
            if (cache.TryGetValue(key, out var m) && m) return m;
            m = new Material(Template(ref transparentTemplate, "Materials/TransparentTemplate", "Universal Render Pipeline/Lit"));
            m.SetColor(BaseColor, color);
            cache[key] = m;
            return m;
        }

        public static Material Unlit(Color color)
        {
            string key = $"ul:{color}";
            if (cache.TryGetValue(key, out var m) && m) return m;
            m = new Material(Template(ref unlitTemplate, "Materials/UnlitTemplate", "Universal Render Pipeline/Unlit"));
            m.SetColor(BaseColor, color);
            cache[key] = m;
            return m;
        }

        public static void SetEmission(Material m, Color c)
        {
            if (!m) return;
            m.SetColor(EmissionColor, c);
        }
    }

    public static class Prim
    {
        /// <summary>Create a primitive with a material; optionally strip its collider.</summary>
        public static GameObject Make(PrimitiveType type, Transform parent, Vector3 localPos, Vector3 localScale,
            Material mat, bool keepCollider = false, string name = null, Quaternion? localRot = null)
        {
            var go = GameObject.CreatePrimitive(type);
            if (name != null) go.name = name;
            go.transform.SetParent(parent, false);
            go.transform.localPosition = localPos;
            go.transform.localRotation = localRot ?? Quaternion.identity;
            go.transform.localScale = localScale;
            if (!keepCollider) { var c = go.GetComponent<Collider>(); if (Application.isPlaying) Object.Destroy(c); else Object.DestroyImmediate(c); }
            var r = go.GetComponent<MeshRenderer>();
            if (mat) r.sharedMaterial = mat;
            return go;
        }
    }
}
